// Reduces TriRank's /api/signals response to ONE honest reading for the
// configured domain, compares it with the reading stored on the previous run
// (workflow static data, no database), and emits `message` only on change.
//
// RED LINE (TriRank's, and this template's): "no citation on record" is NOT
// "not cited". `citation.state === 'none'` means no fresh measurement exists —
// never that the engines declined to cite. Only `state === 'scored'` with an
// empty `cited` list is a real "not cited", because that is the one case where
// all four engines carry a fresh verdict.

const cfg = $('Configure domain').first().json;
const domain = String(cfg.domain || '').trim().toLowerCase();
const notifyOnFirstRun = String(cfg.notifyOnFirstRun) !== 'false';
const res = $input.first().json; // full response: { statusCode, headers, body }
const status = Number(res.statusCode);
const body = res.body && typeof res.body === 'object' ? res.body : null;

const AUDIT_URL = 'https://trirankai.com/audit';
const REPORT_URL = 'https://trirankai.com/site/' + domain;
const ENGINES = 'ChatGPT, Claude, Gemini, Perplexity';

function day(iso) {
  return iso ? String(iso).slice(0, 10) : 'unknown date';
}

// -> { key, text }. `key` is the change signature; `text` is what people read.
function reading() {
  if (status === 429) {
    return {
      key: 'limited',
      text: 'TriRank read was rate-limited (HTTP 429). The daily allowance resets at 00:00 UTC; nothing was measured this run.',
    };
  }
  if (!body || status !== 200) {
    return {
      key: 'error:' + status,
      text: 'TriRank read failed (HTTP ' + status + '). Nothing was measured this run.',
    };
  }
  const c = body.citation || {};
  const a = body.audit || {};
  if (c.state === 'scored') {
    const cited = Array.isArray(c.cited) ? c.cited.slice().sort() : [];
    const when = day(c.checkedAt);
    if (cited.length > 0) {
      return {
        key: 'cited:' + cited.join(','),
        text: 'cited by ' + cited.join(', ') + ' — AI visibility score ' + c.score + '/100 (measured ' + when + ')',
      };
    }
    return {
      key: 'not-cited',
      text: 'measured ' + when + ': none of ' + ENGINES + ' cited it (score ' + c.score + '/100)',
    };
  }
  if (c.state === 'partial') {
    const missing = Array.isArray(c.missing) ? c.missing.slice().sort() : [];
    return {
      key: 'partial:' + missing.join(','),
      text: 'partially measured — not yet checked on ' + missing.join(', '),
    };
  }
  // 'none' — no fresh citation measurement on record. Say why, never "not cited".
  if (a.state === 'not_measured') {
    return {
      key: 'none:unaudited',
      text: 'no citation measurement on record — TriRank has never audited this domain. Run the free audit once: ' + AUDIT_URL,
    };
  }
  return {
    key: 'none:stale',
    text: 'no fresh citation measurement on record (probes expire after 14 days). Re-run the free audit: ' + AUDIT_URL,
  };
}

const now = reading();
// A rejected API key silently downgrades to anonymous; say so once, not weekly.
if (body && body.authError === 'invalid_key') {
  now.key += '|invalid_key';
  now.text += ' ⚠️ The TriRank API key on the HTTP node was rejected; this ran as anonymous.';
}

const store = $getWorkflowStaticData('global');
if (!store.trirankCitationWatch) store.trirankCitationWatch = {};
const prev = store.trirankCitationWatch[domain];
const at = new Date().toISOString();
store.trirankCitationWatch[domain] = { key: now.key, text: now.text, at };

let message = null;
if (!prev) {
  if (notifyOnFirstRun) {
    message = '📌 TriRank baseline for ' + domain + ': ' + now.text + '\n' + REPORT_URL;
  }
} else if (prev.key !== now.key) {
  message =
    '🔔 AI citation change for ' + domain + '\n' +
    'Before (' + day(prev.at) + '): ' + prev.text + '\n' +
    'Now: ' + now.text + '\n' +
    REPORT_URL;
}

return [{ json: { domain, changed: Boolean(prev) && prev.key !== now.key, reading: now.text, message } }];
